for (const topic of topics) {
  if (process.env.ONLY_GUIDELINE && topic.id !== process.env.ONLY_GUIDELINE) continue;
  const { source, summary: _summary, unverified, ...topicContent } = topic;
  const content = DiseaseDetailSchema.parse({ ...topicContent, status: "under_review", version: VERSION, lastReviewed: DATE, clinicalReviewStatus: "pending", evidenceAudit: { checkedOn: DATE, status: "incomplete", scope: `${topic.title}: adult recognition, investigation, emergency escalation and disposition. Gemini was used only as an unverified research scaffold; the final content was independently limited to the opened source named below.`, findings: [`Opened ${source.organisation} source on ${DATE}.`, "No medication doses were copied from Gemini; medicines are held behind local specialist protocol pending product/formulary verification."], unverifiedSections: unverified, medscapeStatus: "unavailable", originalVersionIds: [topic.id] } });
  const audit = auditTopicContent(content);
  console.log(JSON.stringify({ guidelineId: topic.id, title: topic.title, version: VERSION, score: audit.score, publishable: audit.publishable, failures: audit.failures }, null, 2));
  if (!process.argv.includes("--apply")) continue;
  if (!audit.publishable) throw new Error(`${topic.title} did not pass the authoring audit.`);
  const db = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SECRET_KEY!, { auth: { persistSession: false } });
  const { data: exists, error: existsError } = await db.from("guideline_versions").select("id").eq("guideline_id", topic.id).eq("version", VERSION);
  if (existsError) throw existsError;
  if (exists?.length) throw new Error(`${topic.title}: ${VERSION} already exists; refusing to overwrite.`);
  const { data: existing, error: existingError } = await db.from("guideline_versions").select("created_by,jurisdiction").eq("guideline_id", topic.id).eq("is_current", true).single();
  if (existingError) throw existingError;
  const { error: insertError } = await db.from("guideline_versions").insert({ id: randomUUID(), guideline_id: topic.id, version: VERSION, version_number: VERSION, status: "under_review", is_current: false, content, source_title: source.title, issuing_organization: source.organisation, source_url: source.url, jurisdiction: existing.jurisdiction, last_verified_date: DATE, review_date: DATE, created_by: existing.created_by, approved_by: null, approved_at: null, published_at: null, change_summary: "First governed clinical content for this draft. Gemini research was independently constrained to the named official source; all unverified local and medicine details were excluded. Pending clinical review." });
  if (insertError) throw insertError;
  console.log(`STAGED ${topic.title}`);
}
